// Canvas mediator: hermes/canvas/<kind>  ->  wallpanel/canvas/<kind>
//
// The agent never publishes into wallpanel/#. It publishes to its own prefix and
// this node is the only thing that crosses into the panel's namespace, so the
// panel's control topics stay unreachable from the agent even if its credential
// leaks - and validation happens somewhere the agent cannot skip.
//
// Contract: kiosk-display/docs/agent-canvas-schema.md. That file is canonical;
// if this disagrees with it, this is wrong.
//
// Output 1: accepted, ready to republish retained.
// Output 2: rejected, with the reason - wire it to a debug node.

const MAX_BYTES = 64 * 1024;      // the document is small by design; bulk goes
                                  // on the share as a file, not through here
const MAX_TILES = 6;
const MAX_POINTS = 200;
const ASSET_PREFIX = "agent/";

const kind = String(msg.topic || "").endsWith("/ephemeral") ? "ephemeral" : "persistent";
const out = "wallpanel/canvas/" + kind;

function reject(why) {
    node.status({ fill: "yellow", shape: "ring", text: kind + ": " + why });
    return [null, { topic: msg.topic, payload: { rejected: why, kind: kind } }];
}

const raw = (msg.payload === null || msg.payload === undefined)
    ? "" : (typeof msg.payload === "string" ? msg.payload : JSON.stringify(msg.payload));

// An empty payload is how the agent clears its own canvas. Forward it: clearing
// is always valid, and it is the documented way to take a canvas down.
if (raw.trim() === "") {
    node.status({ fill: "grey", shape: "dot", text: kind + ": cleared" });
    return [{ topic: out, payload: "", retain: true }, null];
}

if (raw.length > MAX_BYTES) return reject("payload over " + MAX_BYTES + " bytes");

let d;
try { d = JSON.parse(raw); } catch (e) { return reject("not JSON: " + e.message); }
if (!d || typeof d !== "object" || Array.isArray(d)) return reject("not an object");
if (d.v !== 1) return reject("unsupported schema version: " + d.v);
if (typeof d.title !== "string" || !d.title.trim()) return reject("missing title");
if (typeof d.updated_at !== "string" || isNaN(Date.parse(d.updated_at)))
    return reject("missing or unparseable updated_at");
if (d.subtitle != null && typeof d.subtitle !== "string") return reject("subtitle not a string");
if (d.note != null && typeof d.note !== "string") return reject("note not a string");

if (d.tiles != null) {
    if (!Array.isArray(d.tiles)) return reject("tiles is not an array");
    if (d.tiles.length > MAX_TILES) return reject("more than " + MAX_TILES + " tiles");
    for (let i = 0; i < d.tiles.length; i++) {
        const t = d.tiles[i];
        if (!t || typeof t !== "object") return reject("tile " + i + " is not an object");
        if (typeof t.label !== "string") return reject("tile " + i + " has no label");
        if (t.value === null || t.value === undefined) return reject("tile " + i + " has no value");
        if (t.state != null && ["ok", "warn", "bad"].indexOf(t.state) === -1)
            return reject("tile " + i + " has unknown state " + t.state);
    }
}

if (d.series != null) {
    if (!Array.isArray(d.series)) return reject("series is not an array");
    if (d.series.length > MAX_POINTS) return reject("series longer than " + MAX_POINTS);
    for (let k = 0; k < d.series.length; k++) {
        const p = d.series[k];
        if (!Array.isArray(p) || p.length !== 2 ||
            typeof p[0] !== "number" || typeof p[1] !== "number" ||
            !isFinite(p[0]) || !isFinite(p[1]))
            return reject("series point " + k + " is not [number, number]");
    }
}

// An agent-supplied path aimed at a local filesystem is untrusted input: it has
// to stay inside the mounted share. A bad path rejects the WHOLE payload rather
// than dropping the image, because a canvas quietly missing the thing it was
// published to show is worse than an absent canvas.
if (d.image != null) {
    const v = d.image;
    const ok = typeof v === "string" && v.length > 0 && v.length <= 200 &&
        v.indexOf(ASSET_PREFIX) === 0 &&
        v.indexOf("..") === -1 &&
        v.indexOf(":") === -1 && v.indexOf("//") === -1 &&
        /^[A-Za-z0-9][A-Za-z0-9._/-]*$/.test(v);
    if (!ok) return reject("image path is not inside " + ASSET_PREFIX);
}

if (d.ttl_s != null) {
    if (typeof d.ttl_s !== "number" || !isFinite(d.ttl_s) || d.ttl_s <= 0 || d.ttl_s > 86400)
        return reject("ttl_s must be a positive number of seconds, at most 86400");
    if (kind === "persistent")
        node.warn("ttl_s on the persistent canvas is ignored - it has no TTL");
}

// Rebuild from known fields only. Anything the agent adds beyond the schema is
// dropped here rather than forwarded into the panel's namespace.
const clean = { v: 1, title: d.title, updated_at: d.updated_at };
if (d.subtitle != null) clean.subtitle = d.subtitle;
if (d.tiles != null) clean.tiles = d.tiles.map(function (t) {
    const o = { label: t.label, value: t.value };
    if (t.unit != null) o.unit = t.unit;
    if (t.state != null) o.state = t.state;
    return o;
});
if (d.series != null) clean.series = d.series;
if (d.image != null) clean.image = d.image;
if (d.note != null) clean.note = d.note;
if (kind === "ephemeral" && d.ttl_s != null) clean.ttl_s = d.ttl_s;

node.status({ fill: "green", shape: "dot", text: kind + ": " + d.title.slice(0, 24) });
return [{ topic: out, payload: JSON.stringify(clean), retain: true }, null];
